"""AI Agent Security red-team submission kernel — agent-security-claude champion.

Kaggle code competition (``ai-agent-security-multi-step-tool-attacks``). On the
graded rerun this script serves the ``JEDAttackInferenceServer``, which loads the
attacker's ``/kaggle/working/attack.py`` and runs its ``AttackAlgorithm`` against
the hidden guardrails. We materialise the repo champion ``attack.py`` verbatim
(base64 below is the SOT-2296 genuine-carriage champion, so the submitted
strategy is byte-identical to the locally-evaluated champion ``attack.py``)
rather than inlining a divergent copy. The byte-identity is enforced by
``scripts/test_kernel_payload_identity.py`` (SOT-2315 submission integrity gate).
"""

import base64
import csv
import os
from pathlib import Path

# Verbatim base64 of the current champion attack.py (single-message exfiltration
# raw-weighted fill, adopted from the public aisec-pilk scoring analysis; SHA-256
# 3a9525b578cd9d83659a59525190ffddea68843f2435fb10a601a3f038dd3994). Replaces the
# SOT-2296 genuine-carriage floor champion (SHA-256 0391b1bc…) and the earlier
# SOT-2082 floor champion (SHA-256 e6d75d4b…, ref 55162748 / public-0.000), both
# of which tuned to the local stub agent yet scored public 0.000 on the real
# grader. Keep byte-identical to ``attack.py`` (test_kernel_payload_identity).
_ATTACK_PY_B64 = ""

Path("/kaggle/working/attack.py").write_text(
    base64.b64decode(_ATTACK_PY_B64).decode("utf-8")
)

from kaggle_evaluation.jed_attack_134815.jed_attack_inference_server import (
    JEDAttackInferenceServer,
)

server = JEDAttackInferenceServer()
if os.getenv("KAGGLE_IS_COMPETITION_RERUN"):
    server.serve()
else:
    with open("/kaggle/working/submission.csv", "w", newline="") as handle:
        writer = csv.writer(handle)
        writer.writerow(["Id", "Score"])
        writer.writerows(
            [
                ["gpt_oss_public", 0.0],
                ["gpt_oss_private", 0.0],
                ["gemma_public", 0.0],
                ["gemma_private", 0.0],
            ]
        )
    print("Wrote local-run placeholder submission.csv")
